Lemma up_fast : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t2 s0 s1 a0 a1 a3 a5 s3 s5 s6 s7 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp D : Z) (vbs : list byte) (T3 T1 A2 A6 : Z),
  (7 - j = k)%nat -> (j <= 7)%nat ->
  bytes_at bsegs m1 vp vbs -> accessible m1 vp (Z.of_nat (length vbs)) -> mem_inv bsegs m1 -> ACONST m1 ->
  vp <= D -> D + 7 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
  dof_cont3 Q ADOF_SETF rax spx gp tp s0 s1 (wz 256) (wz ALIT_CLOSE) s3 (wz M1W) s5 s6 s7 (wz 1) (wz 2) (wz M11W) (wz ASHADOW_BASE) F fc m1 ->
  dof_cont Q ADOF_NEXT rax spx gp tp s0 s1 (wz ALIT_CLOSE) s3 (wz M1W) s5 s6 s7 (wz 1) (wz 2) (wz M11W) (wz ASHADOW_BASE) F fc m1 ->
  T3 = ALIT_UPGRADE + Z.of_nat j -> T1 = D + Z.of_nat j -> A2 = 7 - Z.of_nat j -> A6 = Z.of_nat j - 7 ->
  evt bsegs Q (MS (mkR rax spx gp tp t0 (wz T1) t2 s0 s1 a0 a1 (wz A2) a3 (wz D) a5 (wz A6) (wz ALIT_UPGRADE)
                       (wz ALIT_CLOSE) s3 (wz M1W) s5 s6 s7 (wz 1) (wz 2) (wz M11W) (wz ASHADOW_BASE) (wz T3) t4 t5 t6)
                  F (Z_to_bv 64 0xd55a4) fc None m1 (seg_rom bsegs)).
