Lemma ka_slow : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 a0 a1 a7 s3 s5 s6 s7 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp D : Z) (vbs : list byte) (A5 : Z),
  (10 - j = k)%nat -> (j < 10)%nat ->
