(* [comment removed for export] *)
Lemma clo_slow : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 a6 a7 s3 s5 s6 s7 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp D : Z) (vbs : list byte) (P0 P1 P2 P4 N5 : Z),
  (5 - j = k)%nat -> (j < 5)%nat ->
  bytes_at bsegs m1 vp vbs -> accessible m1 vp (Z.of_nat (length vbs)) -> mem_inv bsegs m1 -> ACONST m1 ->
  vp <= D -> D + 5 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
  dof_cont3 Q ADOF_SETF rax spx gp tp s0 s1 (wz 128) (wz ALIT_CLOSE) s3 (wz M1W) s5 s6 s7 (wz 1) (wz 2) (wz M11W) (wz ASHADOW_BASE) F fc m1 ->
  dof_cont Q ADOF_NEXT rax spx gp tp s0 s1 (wz ALIT_CLOSE) s3 (wz M1W) s5 s6 s7 (wz 1) (wz 2) (wz M11W) (wz ASHADOW_BASE) F fc m1 ->
  P0 = ALIT_CLOSE + Z.of_nat j -> P1 = D + Z.of_nat j -> P2 = ALIT_CLOSE + Z.of_nat j -> P4 = D + Z.of_nat j -> N5 = 5 - Z.of_nat j ->
  evt bsegs Q (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 (wz P0) (wz P1) (wz P2) (wz 128) (wz P4) (wz N5) a6 a7
                       (wz ALIT_CLOSE) s3 (wz M1W) s5 s6 s7 (wz 1) (wz 2) (wz M11W) (wz ASHADOW_BASE) t3 t4 t5 t6)
